// Points of a subring of a field with values in a subfield: restriction from
// S[1/d] to S is one to one onto the points that do not kill d, so inverting a
// nonzero element loses exactly the points that kill it, and a monic relation
// bounds the points over a fixed point of the coefficients. So the points
// agreeing on S of a ring S[G] generated by finitely many integral elements are
// boundedly many, one bound for every subfield of values, and so are the points
// over each value of t of a ring finite over k[t].

package algebra_point_bounds

import (
	"github.com/euc-ai/xugo/ext/on"
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/algebraic_element"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/field"
	"github.com/euc-ai/xugo/library/proofs/algebra/group/group"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/module_record"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/principal_ideal_domain"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/submodule"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/algebra_points"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/comm_ring"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/integral_domain"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/integral_element"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/polynomial/polynomial"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/polynomial/polynomial_evaluation"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/polynomial/polynomial_roots"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_away"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_homomorphism"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_ideal"
	"github.com/euc-ai/xugo/library/proofs/iterate/nat/nat_sum"
	"github.com/euc-ai/xugo/library/proofs/nat_num/nat_order"
	"github.com/euc-ai/xugo/library/proofs/sets/cardinality"
	"github.com/euc-ai/xugo/library/proofs/sets/finite_set"
	"github.com/euc-ai/xugo/library/proofs/sets/functions"
	"github.com/euc-ai/xugo/library/proofs/sets/set_basic"
	"github.com/euc-ai/xugo/library/proofs/sets/set_image"
	"github.com/euc-ai/xugo/library/proofs/vector/vec_space"
	"github.com/euc-ai/xugo/library/registry"
)

// AlgebraPointsAwayInFieldRestriction — inside a field, with values in a
// subfield, restriction to S is a bijection from the points of S[1/d] onto the
// points of S that do not kill the nonzero element d: S[1/d] is the localization
// of S at the powers of d (AlgebraPointsAway), and in the subfield a unit is a
// nonzero element.
var AlgebraPointsAwayInFieldRestriction = algebraPointsAwayInFieldRestrictionThm{family.Add(registry.ProofEntry{
	Name: "AlgebraPointsAwayInFieldRestriction",
	Key:  "prop_63eb0c9e4ef83541",
	Build: family.Theorem(Statement{
		Abbrev: Abbrev{
			{Name: "target", Text: "restrict_ring(field_ring(M), l)"},
			{Name: "pointsOf", Text: "λX:set(A). " +
				"    algebra_points(restrict_ring(field_ring(M), X), «target», k, λx:A. x)"},
			{Name: "away", Text: "ring_away(field_ring(M), S, d)"},
			{Name: "inverted", Text: "restrict_ring(field_ring(M), «away»)"},
			{Name: "restriction", Text: "λφ:(A → A). λx:A. COND(x ∈ S, φ(x), M.zero)"},
		},
		Binders: "∀M:field_on(A). ∀S k l:set(A). ∀d:A.",
		Hypotheses: []string{
			"subring(field_ring(M), S)",
			"subfield(M, l)",
			"k ⊆ S",
			"d ∈ S",
			"d ≠ M.zero",
		},
		Conclusion: "injective_on(«pointsOf»(«away»), «restriction») ∧ " +
			"image(«restriction», «pointsOf»(«away»)) = {ψ:A → A | ψ ∈ «pointsOf»(S) ∧ ψ(d) ≠ M.zero}",
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			S, k, l *Expr[Set[A]],
			d *Expr[A],
			subringS, subfieldL, kInS, dInS, nonzero Fact,
		) {
			fieldM := a.TermAs[FieldOps[A]]("M")
			R := a.TermAs[RingOps[A]]("field_ring(M)")
			ring := field.RingOn.Read(M)
			away := a.TermAs[Set[A]]("«away»")
			inverted := a.TermAs[RingOps[A]]("«inverted»")
			target := a.TermAs[RingOps[A]]("«target»")
			chart := a.TermAs[RingOps[A]]("restrict_ring(field_ring(M), S)")
			identity := a.TermAs[Fun[A, A]]("λx:A. x")
			twice := module_record.RestrictRingTwice.At(R, away, S)
			dm := a.MemberOf[on.M](d, a.Have(
				"d lies in M",
				"d ∈ M.carrier",
				BySets(dInS, comm_ring.SubringSubset.Read(subringS))))
			inverse := field.InvIn.Read(M).At(dm)
			localization := a.Have(
				"S[1/d] is the localization of S at the powers of d",
				"is_localization_on(restrict_ring(«inverted», S), "+
					"    monoid_powers(«inverted».mul, «inverted».one, d), "+
					"    «inverted», "+
					"    λx:A. x)",
				By(
					ring,
					dInS,
					subringS,
					inverse,
					nonzero,
					field.MulRightInverseOn.Read(M).At(dm),
					ring_away.RingAwayIsLocalization.At(R, S, d, inverse),
					twice,
					module_record.RingMulDef,
					module_record.RingOneDef,
					module_record.RestrictRingDef))
			bijection := a.Conjuncts(
				a.Have(
					"so restriction to S is a bijection from its points onto the points of S making d a unit",
					"injective_on(«pointsOf»(«away»), «restriction») ∧ "+
						"image(«restriction», «pointsOf»(«away»)) = "+
						"{ψ:A → A | ψ ∈ «pointsOf»(S) ∧ ring_unit(«target», ψ(d))}",
					By(dInS, kInS, localization, AlgebraPointsAway.At(inverted, target, S, k, identity, d), twice)),
				"restriction is injective on the points of S[1/d]",
				"its image is the points of S making d a unit")
			units := a.Have(
				"a point of S makes d a unit exactly when it does not kill d",
				"∀ψ:(A → A). ψ ∈ «pointsOf»(S) ⇒ (ring_unit(«target», ψ(d)) ⇔ ψ(d) ≠ M.zero)",
				Derive(func(b *Argument) {
					ψ := b.FixAs[Fun[A, A]]("ψ")
					point := b.Assume()
					ringMap := b.Have(
						"ψ is a ring map from S to l",
						"ring_homomorphism(restrict_ring(field_ring(M), S), «target», ψ)",
						By(point, algebra_points.AlgebraPointsMember.At(chart, target, k, identity, ψ)))
					value := b.TermAs[A]("ψ(d)")
					inL := b.Have(
						"so ψ(d) lies in l",
						"ψ(d) ∈ l",
						By(dInS, ring_homomorphism.MapIn.Read(ringMap).AsFact().At(d)))
					b.Iff()
					b.Forward(
						"a unit is not zero, zero having no inverse",
						func(c *Argument, unitValue Fact) {
							y, inverse := c.ObtainAs[A](
								"ψ(d) has an inverse in l",
								"∃y:A. y ∈ l ∧ ψ(d) * y = M.one",
								By(unitValue, ring_ideal.RingUnitDef.At(target, value)))
							c.Show(
								"were ψ(d) zero, one would be zero",
								By(
									subfieldL,
									inverse,
									field.SubfieldSubset.At(fieldM, l),
									set_basic.SubsetDef,
									field.OneNotZeroOn.Read(M),
									comm_ring.MulLeftZeroOn.Read(ring).AsFact().At(y)))
						})
					b.Backward(
						"a nonzero element of l has its inverse in l",
						func(c *Argument, nonzeroValue Fact) {
							inverted := c.Have(
								"M inverts ψ(d) inside l",
								"∃y:A. y ∈ l ∧ ψ(d) * y = M.one",
								Witness(c.TermAs[A]("M.inv(ψ(d))")),
								By(
									nonzeroValue,
									inL,
									subfieldL,
									field.SubfieldInv.At(fieldM, l, value),
									field.SubfieldSubset.At(fieldM, l),
									set_basic.SubsetDef,
									field.MulRightInverseOn.Read(M).AsFact().At(value)))
							c.Show(
								"so ψ(d) is a unit of l",
								By(inL, inverted, ring_ideal.RingUnitDef.At(target, value)))
						})
				}))
			sameSet := a.Have(
				"The points making d a unit are the points not killing d",
				"{ψ:A → A | ψ ∈ «pointsOf»(S) ∧ ring_unit(«target», ψ(d))} = "+
					"{ψ:A → A | ψ ∈ «pointsOf»(S) ∧ ψ(d) ≠ M.zero}",
				BySets(units))
			a.Show(
				"Restriction is injective, and its image is the points not killing d",
				By(bijection[0], bijection[1], sameSet))
		}),
})}

// AlgebraPointsAwayInField — inside a field, with values in a subfield, inverting
// a nonzero element d of a subring S loses exactly the points that kill d: the
// points of S[1/d] restrict one to one onto the points of S that do not kill d,
// and those with the points that kill d make up the points of S.
var AlgebraPointsAwayInField = algebraPointsAwayInFieldThm{family.Add(registry.ProofEntry{
	Name: "AlgebraPointsAwayInField",
	Key:  "prop_e7ef4c5cab73e5db",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀S k l:set(A). ∀d:A.",
		Hypotheses: []string{
			"subring(field_ring(M), S)",
			"subfield(M, l)",
			"k ⊆ S",
			"d ∈ S",
			"d ≠ M.zero",
		},
		Conclusion: "(finite(«pointsOf»(S)) ⇔ " +
			"    finite(«pointsOf»(ring_away(field_ring(M), S, d))) ∧ finite(«killed»)) ∧ " +
			"(finite(«pointsOf»(S)) ⇒ " +
			"    card(«pointsOf»(S)) = card(«pointsOf»(ring_away(field_ring(M), S, d))) + card(«killed»))",
		Abbrev: Abbrev{
			{Name: "target", Text: "restrict_ring(field_ring(M), l)"},
			{Name: "pointsOf", Text: "λX:set(A). " +
				"    algebra_points(restrict_ring(field_ring(M), X), «target», k, λx:A. x)"},
			{Name: "killed", Text: "{ψ:A → A | ψ ∈ «pointsOf»(S) ∧ ψ(d) = M.zero}"},
			{Name: "spared", Text: "{ψ:A → A | ψ ∈ «pointsOf»(S) ∧ ψ(d) ≠ M.zero}"},
			{Name: "restriction", Text: "λφ:(A → A). λx:A. COND(x ∈ S, φ(x), M.zero)"},
		},
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			S, k, l *Expr[Set[A]],
			d *Expr[A],
			subringS, subfieldL, kInS, dInS, nonzero Fact,
		) {
			restriction := a.TermAs[Fun[Fun[A, A], Fun[A, A]]]("«restriction»")
			pointsS := a.TermAs[Set[Fun[A, A]]]("«pointsOf»(S)")
			pointsAway := a.TermAs[Set[Fun[A, A]]]("«pointsOf»(ring_away(field_ring(M), S, d))")
			killed := a.TermAs[Set[Fun[A, A]]]("«killed»")
			spared := a.TermAs[Set[Fun[A, A]]]("«spared»")
			bijection := a.Conjuncts(
				GroupPremises(
					subringS,
					subfieldL,
					kInS,
					dInS,
					nonzero,
					AlgebraPointsAwayInFieldRestriction.Read(M).At(S, k, l, d)),
				"restriction is injective on the points of S[1/d]",
				"its image is the points of S that do not kill d")
			injective, imageEq := bijection[0], bijection[1]
			partition := a.Have(
				"a point of S kills d or does not",
				"«killed» ∪ «spared» = «pointsOf»(S) ∧ «killed» ∩ «spared» = ∅",
				BySets())
			imageFinite := a.Have(
				"S[1/d] has finitely many points exactly when S has finitely many not killing d",
				"finite(«spared») ⇔ finite(«pointsOf»(ring_away(field_ring(M), S, d)))",
				imageEq.RwRev(),
				By(injective, finite_set.FiniteImageInjEq.At(restriction, pointsAway)))
			partsFinite := a.Have(
				"S has finitely many points exactly when each part has",
				"finite(«pointsOf»(S)) ⇔ finite(«killed») ∧ finite(«spared»)",
				By(partition, finite_set.FiniteUnion.At(killed, spared)))
			a.Do(SplitConj(
				Case(
					"finiteness is that of the two parts",
					By(imageFinite, partsFinite)),
				Case(
					"and so is the count",
					Derive(func(b *Argument) {
						finitePoints := b.Assume()
						parts := b.Have(
							"S counts its two parts",
							"card(«pointsOf»(S)) = card(«killed») + card(«spared»)",
							By(finitePoints, partition, cardinality.CardOfDisjointParts.At(killed, spared, pointsS)))
						finiteAway := b.Have(
							"S[1/d] has finitely many points",
							"finite(«pointsOf»(ring_away(field_ring(M), S, d)))",
							By(finitePoints, imageFinite, partsFinite))
						counted := b.Have(
							"and as many as the points of S not killing d",
							"card(«spared») = card(«pointsOf»(ring_away(field_ring(M), S, d)))",
							imageEq.RwRev(),
							By(finiteAway, injective, cardinality.CardImageInj.At(restriction, pointsAway)))
						b.Show(
							"adding the two parts",
							ByArith(parts, counted))
					}))))
		}),
})}

// PointsOverRelationBound — inside a field, let z be a root of a monic polynomial g
// over a subring S. Points of S[z] with values in a subfield that agree on S are at
// most deg g many: any two send g to one polynomial ḡ, each sends z to a root of ḡ,
// which is monic of degree at most deg g, and agreeing also at z two of them agree
// on S[z] (integral_element.PolynomialImageAgreement).
var PointsOverRelationBound = pointsOverRelationBoundThm{family.Add(registry.ProofEntry{
	Name: "PointsOverRelationBound",
	Key:  "prop_6315a076e3e89f45",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀S l k:set(A). ∀g:(num → A). ∀z:A. ∀E:set(A → A).",
		Hypotheses: []string{
			"subring(field_ring(M), S)",
			"subfield(M, l)",
			"z ∈ M.carrier",
			"polynomial_over(S, g)",
			"polynomial_monic(g)",
			"polynomial_eval(g, z) = M.zero",
			"E ⊆ algebra_points(«source», «target», k, λx:A. x)",
			"∀e f:(A → A). e ∈ E ∧ f ∈ E ⇒ ∀c:A. c ∈ S ⇒ e(c) = f(c)",
		},
		Conclusion: "finite(E) ∧ card(E) ≤ polynomial_degree(g)",
		Abbrev: Abbrev{
			{Name: "generated", Text: "polynomial_image(field_ring(M), S, z)"},
			{Name: "source", Text: "restrict_ring(field_ring(M), «generated»)"},
			{Name: "target", Text: "restrict_ring(field_ring(M), l)"},
			{Name: "reduced", Text: "λe:(A → A). λi:num. e(g(i))"},
			{Name: "roots", Text: "λe:(A → A). polynomial_roots(M.carrier, «reduced»(e))"},
			{Name: "atZ", Text: "λe:(A → A). e(z)"},
		},
	},
		func(
			arg *Argument,
			M field.FieldFact[on.M],
			S, l, k *Expr[Set[A]],
			g *Arrow[Nat, A],
			z *Expr[A],
			E *Expr[Set[Fun[A, A]]],
			subringS, subfieldL, zIn, over, monic, root, inPoints, agree Fact,
		) {
			fieldM := arg.TermAs[FieldOps[A]]("M")
			R := arg.TermAs[RingOps[A]]("field_ring(M)")
			ring := field.RingOn.Read(M)
			zero := arg.TermAs[A]("M.zero")
			generated := arg.TermAs[Set[A]]("«generated»")
			source := arg.TermAs[RingOps[A]]("«source»")
			target := arg.TermAs[RingOps[A]]("«target»")
			identity := arg.TermAs[Fun[A, A]]("λx:A. x")
			atZ := arg.TermAs[Fun[Fun[A, A], A]]("«atZ»")
			image := arg.Conjuncts(
				arg.Have(
					"S[z] is a subring of M holding S and z",
					"subring(field_ring(M), «generated») ∧ S ⊆ «generated» ∧ z ∈ «generated»",
					By(M, subringS, zIn, algebraic_element.PolynomialImageSubring.At(fieldM, S, z))),
				"S[z] is a subring",
				"S[z] holds S",
				"S[z] holds z")
			sInGenerated, zInGenerated := image[1], image[2]
			lInField := arg.Have(
				"l lies in M",
				"l ⊆ M.carrier",
				By(subfieldL, field.SubfieldSubset.At(fieldM, l)))
			overGenerated := arg.Have(
				"g is a polynomial over S[z]",
				"polynomial_over(«generated», g)",
				By(sInGenerated, over, polynomial.PolynomialOverMono.At(zero, S, generated, g)))
			ringMap := arg.Have(
				"each member of E is a ring map from S[z] into M, zero off S[z]",
				Statement{
					Binders:    "∀e:(A → A).",
					Hypotheses: []string{"e ∈ E"},
					Conclusion: "ring_homomorphism(«source», «target», e) ∧ " +
						"ring_homomorphism(«source», field_ring(M), e) ∧ " +
						"(∀x:A. x ∉ «generated» ⇒ e(x) = M.zero)",
				},
				Derive(func(b *Argument) {
					e := b.FixAs[Fun[A, A]]("e")
					inE := b.Assume()
					point := b.Have(
						"e is a point of S[z]",
						"ring_homomorphism(«source», «target», e) ∧ (∀x:A. x ∉ «generated» ⇒ e(x) = M.zero)",
						By(
							inE,
							inPoints,
							set_basic.SubsetDef,
							algebra_points.AlgebraPointsMember.At(source, target, k, identity, e)))
					b.Show(
						"and l lies in M",
						By(point, ring, lInField, ring_homomorphism.RingHomExtendTarget.At(source, R, e, l)))
				}))
			// A member of E read through ringMap: a ring map from S[z] into l,
			// one into M, and zero off S[z].
			type _PointOfE struct{ intoL, intoM, vanishesOff Fact }
			// readPoint reads ringMap at f, inE stating f ∈ E.
			readPoint := func(b *Argument, f *Expr[Fun[A, A]], inE Fact) _PointOfE {
				parts := b.Conjuncts(
					GroupPremises(inE, ringMap.At(f)),
					"a ring map from S[z] into l",
					"and into M",
					"vanishing off S[z]")
				return _PointOfE{intoL: parts[0], intoM: parts[1], vanishesOff: parts[2]}
			}
			arg.Cases(arg.Term("E = ∅"))
			arg.When(
				"no point, nothing to count",
				func(b *Argument, empty Fact) {
					b.Do(empty.Rw())
					b.Do(SplitConj(
						Case(
							"the empty set is finite",
							By(finite_set.FiniteRules)),
						Case(
							"and has no point",
							ByArith(cardinality.CardClauses))))
				})
			arg.Otherwise(
				"over the reduction of g at one point of E",
				func(b *Argument, nonempty Fact) {
					e0, chosen := b.ObtainAs[Fun[A, A]](
						"E has a point",
						"∃e:(A → A). e ∈ E",
						BySets(nonempty))
					reduced := b.TermAs[Fun[Nat, A]]("«reduced»(e)")
					intoField := readPoint(b, e0, chosen).intoM
					eZero := b.Have(
						"e keeps zero",
						"e(M.zero) = M.zero",
						By(ring_homomorphism.MapZero.Read(intoField)))
					eOne := b.Have(
						"e keeps one",
						"e(M.one) = M.one",
						By(ring_homomorphism.MapOne.Read(intoField)))
					coefficientsIn := b.Have(
						"e sends S[z] into M",
						"∀x:A. x ∈ «generated» ⇒ e(x) ∈ M.carrier",
						By(ring_homomorphism.MapIn.Read(intoField)))
					overField := b.Have(
						"the reduction of g is a polynomial over M",
						"polynomial_over(M.carrier, «reduced»(e))",
						By(
							overGenerated,
							eZero,
							coefficientsIn,
							polynomial.PolynomialOverMap.At(e0, zero, zero, generated, b.TermAs[Set[A]]("M.carrier"), g)))
					degree := b.TermAs[Nat]("polynomial_degree(g)")
					leading := b.Have(
						"its coefficient at the degree of g is one",
						"«reduced»(e, polynomial_degree(g)) = M.one",
						By(Normalized, monic, eOne, polynomial.PolynomialMonicDef))
					vanishing := b.Have(
						"and past the degree of g it vanishes",
						"vec⟨suc(polynomial_degree(g))⟩(«reduced»(e))",
						Unfold(vec_space.VecDef),
						Derive(func(c *Argument) {
							c.Fix()
							past := c.Assume()
							bounded := c.Have(
								"g vanishes there",
								"vec⟨suc(polynomial_degree(g))⟩(g)",
								By(over, polynomial.DegreeVec.At(zero, S, g)))
							c.Show(
								"and e keeps zero",
								By(Normalized, past, eZero, c.Unfolded(bounded, vec_space.VecDef)))
						}))
					nonzero := b.Have(
						"so the reduction is not the zero polynomial",
						"«reduced»(e) ≠ vec_zero",
						Derive(func(c *Argument) {
							same := c.SupposeNot()
							c.Show(
								"its coefficient at the degree of g is one",
								By(same, leading, field.OneNotZeroOn.Read(M), vec_space.VecZeroDef))
						}))
					rootBound := b.Have(
						"so it has at most its degree many roots",
						"finite(«roots»(e)) ∧ card(«roots»(e)) ≤ polynomial_degree(«reduced»(e))",
						By(
							overField,
							nonzero,
							polynomial_roots.RootBound.Read(integral_domain.FieldIntegralDomain.Read(M)).At(reduced)))
					degreeBound := b.Have(
						"and its degree is at most that of g",
						"polynomial_degree(«reduced»(e)) ≤ polynomial_degree(g)",
						By(vanishing, polynomial.DegreeLeast.At(zero, reduced, degree)))
					intoRoots := b.Have(
						"each member of E sends z to a root of the reduction",
						"∀f:(A → A). f ∈ E ⇒ f(z) ∈ «roots»(e)",
						Derive(func(c *Argument) {
							f := c.FixAs[Fun[A, A]]("f")
							inE := c.Assume()
							fMap := readPoint(c, f, inE)
							sameCoefficients := c.Have(
								"f reduces g as e does",
								"«reduced»(e) = «reduced»(f)",
								Funext(),
								Derive(func(d *Argument) {
									d.Fix()
									d.Show(
										"the coefficients lie in S, where e and f agree",
										By(chosen, inE, over, polynomial.PolynomialOverDef.At(zero, S, g), agree))
								}))
							along := c.Have(
								"f carries g at z to the reduction at f(z)",
								"f(polynomial_eval(g, z)) = polynomial_eval(«reduced»(f), f(z))",
								By(
									fMap.intoM,
									overGenerated,
									zInGenerated,
									polynomial_evaluation.EvalAlongHomomorphism.At(source, R, f, g, z)))
							value := c.Have(
								"and g vanishes at z",
								"polynomial_eval(«reduced»(e), f(z)) = M.zero",
								By(root, along, sameCoefficients, ring_homomorphism.MapZero.Read(fMap.intoM)))
							c.Show(
								"so f(z) is a root in M",
								Unfold(polynomial_roots.PolynomialRootsDef),
								BySets(value, zInGenerated, ring_homomorphism.MapIn.Read(fMap.intoM).AsFact().At(z)))
						}))
					injective := b.Have(
						"members of E agreeing at z are equal",
						"injective_on(E, «atZ»)",
						Simp(Fwd(functions.InjectiveOnDef)),
						Derive(func(c *Argument) {
							f := c.FixAs[Fun[A, A]]("f")
							h := c.FixAs[Fun[A, A]]("h")
							given := c.Conjuncts(
								c.Assume(),
								"f lies in E",
								"h lies in E",
								"they agree at z")
							fMap, hMap := readPoint(c, f, given[0]), readPoint(c, h, given[1])
							c.Do(Funext())
							y := c.FixAs[A]("y")
							c.Cases(c.Term("y ∈ «generated»"))
							c.When(
								"on S[z] they agree, S and z generating it",
								func(d *Argument, inGenerated Fact) {
									d.Show(
										"two ring maps agreeing on S and at z agree on S[z]",
										By(
											M,
											fMap.intoL,
											hMap.intoL,
											sInGenerated,
											zInGenerated,
											given[0],
											given[1],
											given[2],
											agree,
											inGenerated,
											integral_element.PolynomialImageAgreement.At(fieldM, target, generated, S, f, h, z, y)))
								})
							c.Otherwise(
								"off S[z] both vanish",
								func(d *Argument, outside Fact) {
									d.Show(
										"both are zero there",
										By(Normalized, outside, fMap.vanishesOff, hMap.vanishesOff))
								})
						}))
					imageInRoots := b.Have(
						"so E injects into the roots",
						"image(«atZ», E) ⊆ «roots»(e)",
						BySets(intoRoots))
					roots := b.TermAs[Set[A]]("«roots»(e)")
					values := b.TermAs[Set[A]]("image(«atZ», E)")
					finiteE := b.Have(
						"E is finite",
						"finite(E)",
						By(
							rootBound,
							imageInRoots,
							injective,
							finite_set.FiniteSubset.At(values, roots),
							finite_set.FiniteImageInjEq.At(atZ, E)))
					counted := b.Have(
						"and has at most as many points as there are roots",
						"card(E) ≤ card(«roots»(e))",
						By(
							finiteE,
							rootBound,
							imageInRoots,
							injective,
							cardinality.CardSubset.At(values, roots),
							cardinality.CardImageInj.At(atZ, E)))
					b.Show(
						"the bounds chain",
						ByArith(finiteE, counted, rootBound, degreeBound))
				})
		}),
})}

// PointsOverValueBound — let z be a root of a monic polynomial g over k[t], for k a
// subfield. The points of k[t][z] with values in a subfield that send t to one value
// are at most deg g many: fixing k and t they agree on k[t] (PointsOverRelationBound).
var PointsOverValueBound = pointsOverValueBoundThm{family.Add(registry.ProofEntry{
	Name: "PointsOverValueBound",
	Key:  "prop_e1095118cb7e1a7e",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀k l:set(A). ∀t z:A. ∀g:(num → A). ∀y:A.",
		Hypotheses: []string{
			"subfield(M, k)",
			"subfield(M, l)",
			"t ∈ M.carrier",
			"z ∈ M.carrier",
			"polynomial_over(«polynomials», g)",
			"polynomial_monic(g)",
			"polynomial_eval(g, z) = M.zero",
		},
		Conclusion: "finite(«fibre») ∧ card(«fibre») ≤ polynomial_degree(g)",
		Abbrev: Abbrev{
			{Name: "polynomials", Text: "polynomial_image(field_ring(M), k, t)"},
			{Name: "generated", Text: "polynomial_image(field_ring(M), «polynomials», z)"},
			{Name: "source", Text: "restrict_ring(field_ring(M), «generated»)"},
			{Name: "target", Text: "restrict_ring(field_ring(M), l)"},
			{Name: "fibre", Text: "{e:A → A | e ∈ algebra_points(«source», «target», k, λx:A. x) ∧ e(t) = y}"},
		},
	},
		func(
			arg *Argument,
			M field.FieldFact[on.M],
			k, l *Expr[Set[A]],
			t, z *Expr[A],
			g *Arrow[Nat, A],
			y *Expr[A],
			subfieldK, subfieldL, tIn, zIn, over, monic, root Fact,
		) {
			fieldM := arg.TermAs[FieldOps[A]]("M")
			polynomials := arg.TermAs[Set[A]]("«polynomials»")
			generated := arg.TermAs[Set[A]]("«generated»")
			source := arg.TermAs[RingOps[A]]("«source»")
			target := arg.TermAs[RingOps[A]]("«target»")
			identity := arg.TermAs[Fun[A, A]]("λx:A. x")
			fibre := arg.TermAs[Set[Fun[A, A]]]("«fibre»")
			line := arg.Conjuncts(
				arg.Have(
					"k[t] is a subring of M holding k and t",
					"subring(field_ring(M), «polynomials») ∧ k ⊆ «polynomials» ∧ t ∈ «polynomials»",
					By(M, subfieldK, tIn, algebraic_element.PolynomialImageRing.At(fieldM, k, t))),
				"k[t] is a subring",
				"k[t] holds k",
				"k[t] holds t")
			tower := arg.Conjuncts(
				arg.Have(
					"so k[t][z] is a subring of M holding k[t] and z",
					"subring(field_ring(M), «generated») ∧ «polynomials» ⊆ «generated» ∧ z ∈ «generated»",
					By(M, line[0], zIn, algebraic_element.PolynomialImageSubring.At(fieldM, polynomials, z))),
				"k[t][z] is a subring",
				"k[t][z] holds k[t]",
				"k[t][z] holds z")
			kInGenerated := arg.Have(
				"k and t lie in k[t][z]",
				"k ⊆ «generated» ∧ t ∈ «generated»",
				BySets(line[1], line[2], tower[1]))
			agree := arg.Have(
				"two points over y agree on k[t]",
				"∀e f:(A → A). e ∈ «fibre» ∧ f ∈ «fibre» ⇒ ∀c:A. c ∈ «polynomials» ⇒ e(c) = f(c)",
				Derive(func(b *Argument) {
					e := b.FixAs[Fun[A, A]]("e")
					f := b.FixAs[Fun[A, A]]("f")
					given := b.Conjuncts(
						b.Have(
							"both are points of k[t][z] sending t to y",
							"e ∈ algebra_points(«source», «target», k, λx:A. x) ∧ "+
								"e(t) = y ∧ "+
								"f ∈ algebra_points(«source», «target», k, λx:A. x) ∧ "+
								"f(t) = y",
							BySets(b.Assume())),
						"e is a point",
						"e sends t to y",
						"f is a point",
						"f sends t to y")
					eMap := b.Have(
						"e is a ring map fixing k",
						"ring_homomorphism(«source», «target», e) ∧ (∀x:A. x ∈ k ⇒ e(x) = x)",
						By(given[0], algebra_points.AlgebraPointsMember.At(source, target, k, identity, e)))
					fMap := b.Have(
						"so is f",
						"ring_homomorphism(«source», «target», f) ∧ (∀x:A. x ∈ k ⇒ f(x) = x)",
						By(given[2], algebra_points.AlgebraPointsMember.At(source, target, k, identity, f)))
					c := b.FixAs[A]("c")
					inPolynomials := b.Assume()
					onK := b.Have(
						"they agree on k",
						"∀x:A. x ∈ k ⇒ e(x) = f(x)",
						By(eMap, fMap))
					b.Show(
						"and at t, so on the ring they generate",
						By(
							M,
							eMap,
							fMap,
							kInGenerated,
							onK,
							given[1],
							given[3],
							inPolynomials,
							integral_element.PolynomialImageAgreement.At(fieldM, target, generated, k, e, f, t, c)))
				}))
			inside := arg.Have(
				"the points over y are points of k[t][z]",
				"«fibre» ⊆ algebra_points(«source», «target», k, λx:A. x)",
				BySets())
			arg.Show(
				"a monic relation of z over k[t] bounds points agreeing on k[t]",
				By(
					M,
					line[0],
					subfieldL,
					zIn,
					over,
					monic,
					root,
					inside,
					agree,
					PointsOverRelationBound.At(fieldM, polynomials, l, k, g, z, fibre)))
		}),
})}

// KilledPointsBound — the points of a ring X holding k and t that kill the value at
// t of a nonzero polynomial u over k send t to a root of u, so they are at most
// deg u · m many when each value of t carries at most m points.
var KilledPointsBound = killedPointsBoundThm{family.Add(registry.ProofEntry{
	Name: "KilledPointsBound",
	Key:  "prop_71563409bf467b42",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀X k l:set(A). ∀t:A. ∀u:(num → A). ∀m:num.",
		Hypotheses: []string{
			"subring(field_ring(M), X)",
			"subfield(M, l)",
			"k ⊆ X",
			"t ∈ X",
			"polynomial_over(k, u)",
			"u ≠ vec_zero",
			"∀y:A. finite(«over»(y)) ∧ card(«over»(y)) ≤ m",
		},
		Conclusion: "finite(«killed») ∧ card(«killed») ≤ polynomial_degree(u) * m",
		Abbrev: Abbrev{
			{Name: "source", Text: "restrict_ring(field_ring(M), X)"},
			{Name: "target", Text: "restrict_ring(field_ring(M), l)"},
			{Name: "chartPoints", Text: "algebra_points(«source», «target», k, λx:A. x)"},
			{Name: "over", Text: "λy:A. {e:A → A | e ∈ «chartPoints» ∧ e(t) = y}"},
			{Name: "killed", Text: "{e:A → A | e ∈ «chartPoints» ∧ e(polynomial_eval(u, t)) = M.zero}"},
			{Name: "atT", Text: "λe:(A → A). e(t)"},
		},
	},
		func(
			arg *Argument,
			M field.FieldFact[on.M],
			X, k, l *Expr[Set[A]],
			t *Expr[A],
			u *Arrow[Nat, A],
			m *Expr[Nat],
			subringX, subfieldL, kInX, tInX, over, nonzero, fibres Fact,
		) {
			fieldM := arg.TermAs[FieldOps[A]]("M")
			zero := arg.TermAs[A]("M.zero")
			source := arg.TermAs[RingOps[A]]("«source»")
			target := arg.TermAs[RingOps[A]]("«target»")
			identity := arg.TermAs[Fun[A, A]]("λx:A. x")
			killed := arg.TermAs[Set[Fun[A, A]]]("«killed»")
			rootSet := arg.TermAs[Set[A]]("polynomial_roots(M.carrier, u)")
			atT := arg.TermAs[Fun[Fun[A, A], A]]("«atT»")
			degree := arg.TermAs[Nat]("polynomial_degree(u)")
			count := arg.TermAs[Nat]("card(polynomial_roots(M.carrier, u))")
			lInField := arg.Have(
				"l lies in M",
				"l ⊆ M.carrier",
				By(subfieldL, field.SubfieldSubset.At(fieldM, l)))
			overX := arg.Have(
				"u is a polynomial over X",
				"polynomial_over(X, u)",
				By(kInX, over, polynomial.PolynomialOverMono.At(zero, k, X, u)))
			kInCarrier := arg.Have(
				"k lies in M",
				"k ⊆ M.carrier",
				BySets(kInX, comm_ring.SubringSubset.Read(subringX)))
			overField := arg.Have(
				"so u is a polynomial over M",
				"polynomial_over(M.carrier, u)",
				By(kInCarrier, over, polynomial.PolynomialOverMono.At(zero, k, arg.TermAs[Set[A]]("M.carrier"), u)))
			rootBound := arg.Conjuncts(
				arg.Have(
					"u has at most its degree many roots",
					"finite(polynomial_roots(M.carrier, u)) ∧ "+
						"card(polynomial_roots(M.carrier, u)) ≤ polynomial_degree(u)",
					By(
						overField,
						nonzero,
						polynomial_roots.RootBound.Read(integral_domain.FieldIntegralDomain.Read(M)).At(u))),
				"the roots are finite",
				"there are at most deg u of them")
			into := arg.Have(
				"a killing point sends t to a root of u",
				"∀e:(A → A). e ∈ «killed» ⇒ «atT»(e) ∈ polynomial_roots(M.carrier, u)",
				Derive(func(b *Argument) {
					e := b.FixAs[Fun[A, A]]("e")
					inKilled := b.Assume()
					parts := b.Conjuncts(
						b.Have(
							"e is a point killing u(t)",
							"e ∈ «chartPoints» ∧ e(polynomial_eval(u, t)) = M.zero",
							BySets(inKilled)),
						"e is a point",
						"e kills u(t)")
					point := b.Conjuncts(
						b.Have(
							"e is a ring map fixing k",
							"ring_homomorphism(«source», «target», e) ∧ (∀x:A. x ∈ k ⇒ e(x) = x)",
							By(parts[0], algebra_points.AlgebraPointsMember.At(source, target, k, identity, e))),
						"e is a ring map",
						"e fixes k")
					coefficients := b.Have(
						"e fixes the coefficients of u",
						"(λi:num. e(u(i))) = u",
						Funext(),
						Derive(func(c *Argument) {
							i := c.FixAs[Nat]("i")
							c.Show(
								"each coefficient lies in k",
								By(over, polynomial.PolynomialOverDef.At(zero, k, u), point[1].At(u.Apply(i))))
						}))
					along := b.Have(
						"e carries the value of u at t to the value at e(t)",
						"e(polynomial_eval(u, t)) = polynomial_eval(λi:num. e(u(i)), e(t))",
						By(point[0], overX, tInX, polynomial_evaluation.EvalAlongHomomorphism.At(source, target, e, u, t)))
					carried := b.Have(
						"so u vanishes at e(t)",
						"polynomial_eval(u, e(t)) = M.zero",
						By(parts[1], along, coefficients))
					inL := b.Have(
						"and e(t) lies in M",
						"e(t) ∈ M.carrier",
						BySets(tInX, lInField, ring_homomorphism.MapIn.Read(point[0]).AsFact().At(t)))
					b.Show(
						"so it is a root",
						Unfold(polynomial_roots.PolynomialRootsDef),
						BySets(carried, inL))
				}))
			fibreBound := arg.Have(
				"over each root lie at most m killing points",
				Statement{
					Binders:    "∀y:A.",
					Hypotheses: []string{"y ∈ polynomial_roots(M.carrier, u)"},
					Conclusion: "finite({e:A → A | e ∈ «killed» ∧ «atT»(e) = y}) ∧ " +
						"card({e:A → A | e ∈ «killed» ∧ «atT»(e) = y}) ≤ m",
				},
				Derive(func(b *Argument) {
					y := b.FixAs[A]("y")
					b.Assume()
					part := b.TermAs[Set[Fun[A, A]]]("{e:A → A | e ∈ «killed» ∧ «atT»(e) = y}")
					whole := b.TermAs[Set[Fun[A, A]]]("«over»(y)")
					bound := b.Conjuncts(
						b.Have(
							"all the points over y are bounded",
							"finite(«over»(y)) ∧ card(«over»(y)) ≤ m",
							By(fibres.At(y))),
						"they are finite",
						"they number at most m")
					inside := b.Have(
						"and the killing ones are among them",
						"{e:A → A | e ∈ «killed» ∧ «atT»(e) = y} ⊆ «over»(y)",
						BySets())
					finitePart := b.Have(
						"so they are finite",
						"finite({e:A → A | e ∈ «killed» ∧ «atT»(e) = y})",
						By(bound[0], inside, finite_set.FiniteSubset.At(part, whole)))
					smaller := b.Have(
						"and at most as many",
						"card({e:A → A | e ∈ «killed» ∧ «atT»(e) = y}) ≤ card(«over»(y))",
						By(bound[0], inside, cardinality.CardSubset.At(part, whole)))
					b.Show(
						"as claimed",
						ByArith(finitePart, smaller, bound[1]))
				}))
			counted := arg.Conjuncts(
				arg.Have(
					"so the killing points are finite, at most card(roots) · m many",
					"finite(«killed») ∧ card(«killed») ≤ card(polynomial_roots(M.carrier, u)) * m",
					By(rootBound[0], into, fibreBound, nat_sum.CardFibresBound.At(killed, rootSet, atT, m))),
				"the killing points are finite",
				"at most card(roots) · m many")
			arg.Show(
				"and card(roots) is at most deg u",
				By(
					counted[0],
					counted[1],
					rootBound[1],
					nat_order.LessEqTrans.At(
						arg.TermAs[Nat]("card(«killed»)"),
						arg.TermAs[Nat]("card(polynomial_roots(M.carrier, u)) * m"),
						arg.TermAs[Nat]("polynomial_degree(u) * m")),
					nat_order.LessEqMulRightCancel.At(count, degree, m)))
		}),
})}

// AgreeingPointsBound — let S be a subring of a field M holding k, and G a finite
// set of elements integral over S. There is a bound m such that, for every subfield
// l, a set of points of S[G] fixing k, with values in l, that agree on S has at most
// m members.
// By induction on G: S[∅] = S, and two points of S agreeing on S are equal. For
// S[G ∪ {x}] = S[G][x], restriction to S[G] sends the set into a set of points of
// S[G] agreeing on S, at most m of them, and the points over one restriction agree on
// S[G], so they number at most the degree of a monic equation of x over S
// (PointsOverRelationBound).
var AgreeingPointsBound = agreeingPointsBoundThm{family.Add(registry.ProofEntry{
	Name: "AgreeingPointsBound",
	Key:  "prop_b751713759e69bc9",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀S k G:set(A).",
		Hypotheses: []string{
			"subring(field_ring(M), S)",
			"k ⊆ S",
			"finite(G)",
			"G ⊆ M.carrier",
			"∀z:A. z ∈ G ⇒ integral_over(restrict_ring(field_ring(M), S), z)",
		},
		Conclusion: "∃m:num. ∀l:set(A). ∀F:set(A → A). " +
			"    subfield(M, l) ∧ " +
			"    F ⊆ «generatedPoints»(G, l) ∧ " +
			"    (∀e f:A → A. ∀c:A. e ∈ F ∧ f ∈ F ∧ c ∈ S ⇒ e(c) = f(c)) ⇒ " +
			"    finite(F) ∧ card(F) ≤ m",
		Abbrev: Abbrev{
			{Name: "generated", Text: "λH:set(A). generated_subring(field_ring(M), S, H)"},
			{Name: "generatedPoints", Text: "λH:set(A). λl:set(A). " +
				"    algebra_points(restrict_ring(field_ring(M), «generated»(H)), " +
				"        restrict_ring(field_ring(M), l), " +
				"        k, " +
				"        λx:A. x)"},
			{Name: "bounded", Text: "λH:set(A). " +
				"    H ⊆ M.carrier ∧ (∀z:A. z ∈ H ⇒ integral_over(restrict_ring(field_ring(M), S), z)) ⇒ " +
				"    ∃m:num. ∀l:set(A). ∀F:set(A → A). " +
				"        subfield(M, l) ∧ " +
				"        F ⊆ «generatedPoints»(H, l) ∧ " +
				"        (∀e f:A → A. ∀c:A. e ∈ F ∧ f ∈ F ∧ c ∈ S ⇒ e(c) = f(c)) ⇒ " +
				"        finite(F) ∧ card(F) ≤ m"},
			{Name: "restriction", Text: "λH:set(A). λφ:(A → A). λy:A. COND(y ∈ «generated»(H), φ(y), M.zero)"},
		},
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			S, k, G *Expr[Set[A]],
			subS, kInS, finiteG, gInField, integral Fact,
		) {
			ring := field.RingOn.Read(M)
			identity := a.TermAs[Fun[A, A]]("λx:A. x")
			zero := a.TermAs[A]("M.zero")
			induction := a.Have(
				"adjoining a finite set of integral elements keeps the agreeing points bounded",
				"∀H:set(A). finite(H) ⇒ «bounded»(H)",
				ByInduction(finite_set.FiniteInduct,
					Case(
						"S[∅] is S, whose points agreeing on S are one",
						Derive(func(b *Argument) {
							b.Assume()
							b.Take(b.TermAs[Nat]("1"))
							b.FixAs[Set[A]]("l")
							b.FixAs[Set[Fun[A, A]]]("F")
							given := b.Conjuncts(
								b.Assume(),
								"l is a subfield",
								"F consists of points of S[∅]",
								"its members agree on S")
							same := b.Have(
								"leastness makes S[∅] the ring S",
								"«generated»(∅) = S",
								BySets(subS, algebraic_element.GeneratedSubringStructure.Read(M).At(S, b.TermAs[Set[A]]("∅"))))
							source := b.TermAs[RingOps[A]]("restrict_ring(field_ring(M), S)")
							target := b.TermAs[RingOps[A]]("restrict_ring(field_ring(M), l)")
							equal := b.Have(
								"two members of F are equal: they agree on S and vanish off it",
								"∀f₁ f₂:(A → A). f₁ ∈ F ∧ f₂ ∈ F ⇒ f₁ = f₂",
								Derive(func(c *Argument) {
									f1 := c.FixAs[Fun[A, A]]("f₁")
									f2 := c.FixAs[Fun[A, A]]("f₂")
									both := c.Assume()
									points := c.Have(
										"both are points of S",
										"f₁ ∈ "+
											"algebra_points(restrict_ring(field_ring(M), S), restrict_ring(field_ring(M), l), k, λx:A. x) ∧ "+
											"f₂ ∈ algebra_points(restrict_ring(field_ring(M), S), restrict_ring(field_ring(M), l), k, λx:A. x)",
										BySets(both, given[1], same))
									vanish := c.Have(
										"so both vanish off S",
										"∀x:A. x ∉ S ⇒ f₁(x) = M.zero ∧ f₂(x) = M.zero",
										By(
											points,
											algebra_points.AlgebraPointsMember.At(source, target, k, identity, f1),
											algebra_points.AlgebraPointsMember.At(source, target, k, identity, f2)))
									c.Do(Funext())
									c.Show(
										"at a point of S they agree, and off S both are zero",
										c.ForEach(func(x *Expr[A]) Action {
											return By(Normalized, given[2].At(f1, f2, x), both, vanish.At(x))
										}))
								}))
							single := b.Have(
								"so F lies in the singleton of a chosen member",
								"F ⊆ {εf:A → A. f ∈ F}",
								BySets(equal))
							b.Show(
								"a set inside a singleton has at most one member",
								By(single, cardinality.AtMostOneIffInSingleton))
						})),
					Case(
						"adjoining x to s multiplies the bound by the degree of a monic equation of x",
						Derive(func(b *Argument) {
							x := b.FixAs[A]("x")
							s := b.FixAs[Set[A]]("s")
							bounded := b.Assume()
							inserted := b.Assume()
							data := b.Conjuncts(
								b.Have(
									"x lies in M and is integral over S, and so is every member of s",
									"x ∈ M.carrier ∧ "+
										"integral_over(restrict_ring(field_ring(M), S), x) ∧ "+
										"s ⊆ M.carrier ∧ "+
										"(∀z:A. z ∈ s ⇒ integral_over(restrict_ring(field_ring(M), S), z))",
									BySets(inserted)),
								"x lies in M",
								"x is integral over S",
								"s lies in M",
								"s is integral over S")
							m, boundedS := b.ObtainAs[Nat](
								"the points of S[s] agreeing on S number at most some m",
								"∃m:num. ∀l:set(A). ∀F:set(A → A). "+
									"    subfield(M, l) ∧ "+
									"    F ⊆ «generatedPoints»(s, l) ∧ "+
									"    (∀e f:A → A. ∀c:A. e ∈ F ∧ f ∈ F ∧ c ∈ S ⇒ e(c) = f(c)) ⇒ "+
									"    finite(F) ∧ card(F) ≤ m",
								By(bounded, data[2], data[3]))
							p, relation := b.ObtainAs[Fun[Nat, A]](
								"x is a root of a monic polynomial p over S",
								"∃p:(num → A). "+
									"    polynomial_over(S, p) ∧ "+
									"    polynomial_monic(p) ∧ "+
									"    0 < polynomial_degree(p) ∧ "+
									"    polynomial_eval(p, x) = M.zero",
								By(
									data[1],
									integral_element.IntegralOverDef.At(b.TermAs[RingOps[A]]("restrict_ring(field_ring(M), S)"), x)))
							equation := b.Conjuncts(
								relation,
								"p lies over S",
								"p is monic",
								"p has positive degree",
								"p vanishes at x")
							degree := b.TermAs[Nat]("polynomial_degree(p)")
							b.Take(b.TermAs[Nat]("m * polynomial_degree(p)"))
							l := b.FixAs[Set[A]]("l")
							F := b.FixAs[Set[Fun[A, A]]]("F")
							given := b.Conjuncts(
								b.Assume(),
								"l is a subfield",
								"F consists of points of S[insert(x, s)]",
								"its members agree on S")
							T := b.TermAs[Set[A]]("«generated»(s)")
							U := b.TermAs[Set[A]]("«generated»(insert(x, s))")
							xm := b.MemberOf[on.M](x, data[0])
							structureT := b.Have(
								"S[s] is the least subring holding S and s",
								"subring(field_ring(M), «generated»(s)) ∧ "+
									"S ∪ s ⊆ «generated»(s) ∧ "+
									"(∀B:set(A). subring(field_ring(M), B) ∧ S ∪ s ⊆ B ⇒ «generated»(s) ⊆ B)",
								By(subS, data[2], algebraic_element.GeneratedSubringStructure.Read(M).At(S, s)))
							structureU := b.Have(
								"S[insert(x, s)] is the least subring holding S, x and s",
								"subring(field_ring(M), «generated»(insert(x, s))) ∧ "+
									"S ∪ insert(x, s) ⊆ «generated»(insert(x, s)) ∧ "+
									"(∀B:set(A). subring(field_ring(M), B) ∧ S ∪ insert(x, s) ⊆ B ⇒ «generated»(insert(x, s)) ⊆ B)",
								By(
									subS,
									inserted,
									algebraic_element.GeneratedSubringStructure.Read(M).At(S, b.TermAs[Set[A]]("insert(x, s)"))))
							sInT := b.Have(
								"S lies in S[s]",
								"S ⊆ «generated»(s)",
								BySets(structureT))
							kInT := b.Have(
								"and so does k",
								"k ⊆ «generated»(s)",
								BySets(kInS, sInT))
							adjoinedRing := b.Have(
								"S[s][x] is a subring holding S[s] and x",
								"subring(field_ring(M), polynomial_image(field_ring(M), «generated»(s), x)) ∧ "+
									"«generated»(s) ⊆ polynomial_image(field_ring(M), «generated»(s), x) ∧ "+
									"x ∈ polynomial_image(field_ring(M), «generated»(s), x)",
								By(structureT, algebraic_element.PolynomialImageSubring.Read(M).At(T, xm)))
							rings := b.Conjuncts(
								b.Have(
									"S[s] and S[insert(x, s)] are rings under M's operations",
									"comm_ring_on(restrict_ring(field_ring(M), «generated»(s))) ∧ "+
										"comm_ring_on(restrict_ring(field_ring(M), «generated»(insert(x, s))))",
									By(
										structureT,
										structureU,
										comm_ring.SubringRingOn.Read(ring).At(T),
										comm_ring.SubringRingOn.Read(ring).At(U))),
								"S[s] is a ring",
								"S[insert(x, s)] is a ring")
							oldInNew := b.Have(
								"S[s] lies in S[insert(x, s)]",
								"«generated»(s) ⊆ «generated»(insert(x, s))",
								BySets(structureT, structureU))
							newInAdjoined := b.Have(
								"S[s][x] holds S, x and s, so it holds S[insert(x, s)]",
								"«generated»(insert(x, s)) ⊆ polynomial_image(field_ring(M), «generated»(s), x)",
								BySets(structureT, structureU, adjoinedRing))
							adjoinedInNew := b.Have(
								"S[insert(x, s)] holds S[s] and x, so it holds S[s][x]",
								"polynomial_image(field_ring(M), «generated»(s), x) ⊆ «generated»(insert(x, s))",
								BySets(oldInNew, rings[1], structureU, algebraic_element.PolynomialImageLeast.Read(M).At(T, U, x)))
							adjoined := b.Have(
								"so S[insert(x, s)] is S[s][x]",
								"«generated»(insert(x, s)) = polynomial_image(field_ring(M), «generated»(s), x)",
								BySets(newInAdjoined, adjoinedInNew))
							fieldRing := b.TermAs[RingOps[A]]("field_ring(M)")
							source := b.TermAs[RingOps[A]]("restrict_ring(field_ring(M), «generated»(insert(x, s)))")
							target := b.TermAs[RingOps[A]]("restrict_ring(field_ring(M), l)")
							restricted := b.Have(
								"a member of F restricted to S[s] is a point of S[s], equal to it on S[s]",
								Statement{
									Binders:    "∀φ:A → A.",
									Hypotheses: []string{"φ ∈ F"},
									Conclusion: "«restriction»(s, φ) ∈ «generatedPoints»(s, l) ∧ " +
										"(∀y:A. y ∈ «generated»(s) ⇒ «restriction»(s, φ, y) = φ(y))",
								},
								Derive(func(c *Argument) {
									φ := c.FixAs[Fun[A, A]]("φ")
									member := c.Assume()
									point := c.Conjuncts(
										c.Have(
											"φ is a ring map on S[insert(x, s)] fixing k",
											"ring_homomorphism(restrict_ring(field_ring(M), «generated»(insert(x, s))), "+
												"    restrict_ring(field_ring(M), l), "+
												"    φ) ∧ "+
												"(∀y:A. y ∈ k ⇒ φ(y) = y)",
											By(
												member,
												given[1],
												algebra_points.AlgebraPointsMember.At(source, target, k, identity, φ),
												set_basic.SubsetDef)),
										"φ is a ring map",
										"φ fixes k")
									onT := c.Have(
										"a ring map restricts to a subring of its source, "+
											"so φ is one on S[s], a subring of S[insert(x, s)]",
										"ring_homomorphism(restrict_ring(field_ring(M), «generated»(s)), "+
											"    restrict_ring(field_ring(M), l), "+
											"    φ)",
										By(
											point[0],
											structureT,
											oldInNew,
											comm_ring.SubringRestrict.At(fieldRing, T, U),
											ring_homomorphism.RingHomRestrictSource.At(source, target, φ, T),
											module_record.RestrictRingTwice.At(fieldRing, U, T)))
									c.Show(
										"set to zero off S[s], it is a point of S[s]",
										By(
											onT,
											kInT,
											point[1],
											algebra_points.AlgebraPointsOfRingMap.At(
												b.TermAs[RingOps[A]]("restrict_ring(field_ring(M), «generated»(s))"), target, k, identity, φ)))
								}))
							restriction := b.TermAs[Fun[Fun[A, A], Fun[A, A]]]("«restriction»(s)")
							images := b.TermAs[Set[Fun[A, A]]]("image(«restriction»(s), F)")
							imageIn := b.Have(
								"the restrictions are points of S[s]",
								"image(«restriction»(s), F) ⊆ «generatedPoints»(s, l)",
								By(
									restricted,
									set_image.ImageSubsetIff.At(restriction, F, b.TermAs[Set[Fun[A, A]]]("«generatedPoints»(s, l)"))))
							imageAgree := b.Have(
								"and they agree on S, where they are the members of F",
								Statement{
									Binders: "∀e f:(A → A). ∀c:A.",
									Hypotheses: []string{
										"e ∈ image(«restriction»(s), F)",
										"f ∈ image(«restriction»(s), F)",
										"c ∈ S",
									},
									Conclusion: "e(c) = f(c)",
								},
								Derive(func(d *Argument) {
									e := d.FixAs[Fun[A, A]]("e")
									f := d.FixAs[Fun[A, A]]("f")
									c := d.FixAs[A]("c")
									held := d.Conjuncts(
										d.Assume(),
										"e is a restriction",
										"f is a restriction",
										"c lies in S")
									φ1, eIs := d.ObtainAs[Fun[A, A]](
										"e restricts some φ₁ in F",
										"∃φ₁:A → A. e = «restriction»(s, φ₁) ∧ φ₁ ∈ F",
										By(held[0], set_basic.InImage.At(restriction, F, e)))
									φ2, fIs := d.ObtainAs[Fun[A, A]](
										"f restricts some φ₂ in F",
										"∃φ₂:A → A. f = «restriction»(s, φ₂) ∧ φ₂ ∈ F",
										By(held[1], set_basic.InImage.At(restriction, F, f)))
									inT := d.Have(
										"c lies in S[s]",
										"c ∈ «generated»(s)",
										BySets(held[2], sInT))
									agree := d.Have(
										"φ₁ and φ₂ agree at c",
										"φ₁(c) = φ₂(c)",
										By(eIs, fIs, held[2], given[2].At(φ1, φ2, c)))
									d.Show(
										"so do their restrictions",
										By(eIs, fIs, agree, inT))
								}))
							imageBound := b.Conjuncts(
								b.Have(
									"so there are at most m restrictions",
									"finite(image(«restriction»(s), F)) ∧ card(image(«restriction»(s), F)) ≤ m",
									By(boundedS.At(l, images), given[0], imageIn, imageAgree)),
								"the restrictions are finite",
								"at most m")
							overT := b.Have(
								"p lies over S[s]",
								"polynomial_over(«generated»(s), p)",
								By(equation[0], sInT, polynomial.PolynomialOverMono.At(zero, S, T, p)))
							inAdjoined := b.Have(
								"F consists of points of S[s][x]",
								"F ⊆ "+
									"algebra_points( "+
									"    restrict_ring(field_ring(M), polynomial_image(field_ring(M), «generated»(s), x)), "+
									"    restrict_ring(field_ring(M), l), "+
									"    k, "+
									"    λz:A. z)",
								BySets(given[1], adjoined))
							fibres := b.Have(
								"over each restriction lie at most deg p members of F",
								Statement{
									Binders:    "∀ψ:A → A.",
									Hypotheses: []string{"ψ ∈ image(«restriction»(s), F)"},
									Conclusion: "finite({φ:A → A | φ ∈ F ∧ «restriction»(s, φ) = ψ}) ∧ " +
										"card({φ:A → A | φ ∈ F ∧ «restriction»(s, φ) = ψ}) ≤ polynomial_degree(p)",
								},
								Derive(func(c *Argument) {
									c.FixAs[Fun[A, A]]("ψ")
									c.Assume()
									fibre := c.TermAs[Set[Fun[A, A]]]("{φ:A → A | φ ∈ F ∧ «restriction»(s, φ) = ψ}")
									inside := c.Have(
										"they are points of S[s][x]",
										"{φ:A → A | φ ∈ F ∧ «restriction»(s, φ) = ψ} ⊆ "+
											"algebra_points( "+
											"    restrict_ring(field_ring(M), polynomial_image(field_ring(M), «generated»(s), x)), "+
											"    restrict_ring(field_ring(M), l), "+
											"    k, "+
											"    λz:A. z)",
										BySets(inAdjoined))
									agree := c.Have(
										"they agree on S[s], where each is ψ",
										Statement{
											Binders: "∀e f:A → A.",
											Hypotheses: []string{
												"e ∈ {φ:A → A | φ ∈ F ∧ «restriction»(s, φ) = ψ}",
												"f ∈ {φ:A → A | φ ∈ F ∧ «restriction»(s, φ) = ψ}",
											},
											Conclusion: "∀c:A. c ∈ «generated»(s) ⇒ e(c) = f(c)",
										},
										Derive(func(d *Argument) {
											e := d.FixAs[Fun[A, A]]("e")
											f := d.FixAs[Fun[A, A]]("f")
											both := d.Assume()
											members := d.Have(
												"e and f lie in F and restrict to ψ",
												"e ∈ F ∧ «restriction»(s, e) = ψ ∧ f ∈ F ∧ «restriction»(s, f) = ψ",
												BySets(both))
											d.FixAs[A]("c")
											inT := d.Assume()
											d.Show(
												"each is its restriction there",
												By(members, restricted.At(e), restricted.At(f), inT))
										}))
									c.Show(
										"x is a root of the monic p over S[s]",
										By(
											structureT,
											given[0],
											overT,
											equation[1],
											equation[3],
											inside,
											agree,
											PointsOverRelationBound.Read(M).At(T, l, k, p, xm, fibre)))
								}))
							into := b.Have(
								"each member of F restricts into the image",
								"∀φ:(A → A). φ ∈ F ⇒ «restriction»(s, φ) ∈ image(«restriction»(s), F)",
								By(At(set_image.FunInImage, restriction, F)))
							counted := b.Conjuncts(
								b.Have(
									"so F has at most card(image) · deg p members",
									"finite(F) ∧ card(F) ≤ card(image(«restriction»(s), F)) * polynomial_degree(p)",
									By(imageBound[0], fibres, into, nat_sum.CardFibresBound.At(F, images, restriction, degree))),
								"F is finite",
								"F has at most card(image) · deg p members")
							b.Show(
								"which is at most m · deg p",
								ByArith(
									counted[0],
									counted[1],
									imageBound[1],
									nat_order.LessEqMul2.At(b.TermAs[Nat]("card(image(«restriction»(s), F))"), m, degree, degree)))
						}))))
			a.Show(
				"the finite set G gives the bound",
				By(induction.At(G), finiteG, gInField, integral))
		}),
})}

// UniformFibreBound — let X be a subring of a field M holding a subfield k and t,
// finitely generated as a module over k[t]. There is a bound m such that, for every
// subfield l and every value y, at most m points of X with values in l send t to y.
// Points over y agree on k[t], fixing k and sending t to y; X is k[t][G] for a finite
// set G spanning it, each member of G integral over k[t]
// (principal_ideal_domain.FiniteSubringIntegral); so AgreeingPointsBound applies.
var UniformFibreBound = uniformFibreBoundThm{family.Add(registry.ProofEntry{
	Name: "UniformFibreBound",
	Key:  "prop_75987e0bc44a7cb",
	Build: family.Theorem(Statement{
		Binders: "∀M:field_on(A). ∀X k:set(A). ∀t:A.",
		Hypotheses: []string{
			"subring(field_ring(M), X)",
			"subfield(M, k)",
			"k ⊆ X",
			"t ∈ X",
			"module_finitely_generated(restrict_ring(field_ring(M), «line»), " +
				"    restrict_module(regular_module(field_ring(M)), X))",
		},
		Conclusion: "∃m:num. ∀l:set(A). ∀y:A. " +
			"    subfield(M, l) ⇒ finite(«over»(l, y)) ∧ card(«over»(l, y)) ≤ m",
		Abbrev: Abbrev{
			{Name: "line", Text: "polynomial_image(field_ring(M), k, t)"},
			{Name: "generated", Text: "λH:set(A). generated_subring(field_ring(M), «line», H)"},
			{Name: "over", Text: "λl:set(A). λy:A. " +
				"    {e:A → A | " +
				"        e ∈ " +
				"        algebra_points(restrict_ring(field_ring(M), X), " +
				"            restrict_ring(field_ring(M), l), " +
				"            k, " +
				"            λx:A. x) ∧ " +
				"        e(t) = y}"},
		},
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			X, k *Expr[Set[A]],
			t *Expr[A],
			subX, subK, kInX, tInX, finitelyGenerated Fact,
		) {
			ring := field.RingOn.Read(M)
			R := a.TermAs[RingOps[A]]("field_ring(M)")
			lineRingOps := a.TermAs[RingOps[A]]("restrict_ring(field_ring(M), «line»)")
			vectors := a.TermAs[module_record.ModuleOps[A, A]](
				"restrict_module(regular_module(field_ring(M)), X)")
			line := a.TermAs[Set[A]]("«line»")
			identity := a.TermAs[Fun[A, A]]("λx:A. x")
			tInField := a.Have(
				"t lies in M",
				"t ∈ M.carrier",
				BySets(tInX, subX, comm_ring.SubringSubset.At(R, X)))
			tm := a.MemberOf[on.M](t, tInField)
			lineRing := a.Have(
				"k[t] is a subring holding k and t",
				"subring(field_ring(M), «line») ∧ k ⊆ «line» ∧ t ∈ «line»",
				By(
					subK,
					field.SubfieldSubring.Read(M).At(k),
					algebraic_element.PolynomialImageSubring.Read(M).At(k, tm)))
			lineInX := a.Have(
				"X holds k[t]",
				"«line» ⊆ X",
				By(
					subX,
					kInX,
					tInX,
					comm_ring.SubringRingOn.Read(ring).At(X),
					algebraic_element.PolynomialImageLeast.Read(M).At(k, X, t)))
			G, generating := a.ObtainAs[Set[A]](
				"finitely many elements G of X span it over k[t]",
				"∃G:set(A). "+
					"    finite(G) ∧ "+
					"    G ⊆ X ∧ "+
					"    module_span(restrict_ring(field_ring(M), «line»), "+
					"        restrict_module(regular_module(field_ring(M)), X), "+
					"        G) = "+
					"    X",
				By(finitelyGenerated, principal_ideal_domain.FinitelyGeneratedDef.At(lineRingOps, vectors)))
			parts := a.Conjuncts(
				generating,
				"G is finite",
				"G lies in X",
				"G spans X over k[t]")
			gInField := a.Have(
				"G lies in M",
				"G ⊆ M.carrier",
				BySets(parts[1], subX, comm_ring.SubringSubset.At(R, X)))
			integral := a.Have(
				"each member of G is integral over k[t], X being a finite k[t]-module",
				"∀z:A. z ∈ G ⇒ integral_over(restrict_ring(field_ring(M), «line»), z)",
				Derive(func(b *Argument) {
					z := b.FixAs[A]("z")
					zIn := b.Assume()
					b.Show(
						"a member of a ring finite over k[t] is integral",
						By(
							finitelyGenerated,
							subX,
							lineInX,
							lineRing,
							parts[1],
							zIn,
							principal_ideal_domain.FiniteSubringIntegral.Read(M).At(line, X, z),
							set_basic.SubsetDef))
				}))
			m, bound := a.ObtainAs[Nat](
				"the points of k[t][G] agreeing on k[t] number at most some m",
				"∃m:num. ∀l:set(A). ∀F:set(A → A). "+
					"    subfield(M, l) ∧ "+
					"    F ⊆ "+
					"    algebra_points(restrict_ring(field_ring(M), «generated»(G)), "+
					"        restrict_ring(field_ring(M), l), "+
					"        k, "+
					"        λx:A. x) ∧ "+
					"    (∀e f:A → A. ∀c:A. e ∈ F ∧ f ∈ F ∧ c ∈ «line» ⇒ e(c) = f(c)) ⇒ "+
					"    finite(F) ∧ card(F) ≤ m",
				By(lineRing, gInField, parts[0], integral, AgreeingPointsBound.Read(M).At(line, k, G)))
			generated := a.TermAs[Set[A]]("«generated»(G)")
			structure := a.Conjuncts(
				a.Have(
					"k[t][G] is the least subring holding k[t] and G",
					"subring(field_ring(M), «generated»(G)) ∧ "+
						"«line» ∪ G ⊆ «generated»(G) ∧ "+
						"(∀B:set(A). subring(field_ring(M), B) ∧ «line» ∪ G ⊆ B ⇒ «generated»(G) ⊆ B)",
					By(lineRing, gInField, algebraic_element.GeneratedSubringStructure.Read(M).At(line, G))),
				"k[t][G] is a subring",
				"it holds k[t] and G",
				"it lies in every subring holding k[t] and G")
			insideX := a.Have(
				"X holds k[t] and G, so it holds k[t][G]",
				"«generated»(G) ⊆ X",
				BySets(structure[2], subX, lineInX, parts[1]))
			submoduleOfX := a.Have(
				"k[t][G] is a k[t]-submodule of X",
				"submodule(restrict_ring(field_ring(M), «line»), "+
					"    restrict_module(regular_module(field_ring(M)), X), "+
					"    «generated»(G))",
				// A submodule is an additive subgroup closed under the scalars of k[t]:
				// unfolded, its clauses are closure laws of the subring k[t][G] ⊇ k[t].
				Unfold(submodule.SubmoduleDef),
				Unfold(group.SubgroupDef),
				BySets(structure[0], structure[1], insideX, comm_ring.SubringDef.At(R, generated)))
			equal := a.Have(
				"holding G, it holds the span of G, which is X",
				"X = «generated»(G)",
				BySets(
					submoduleOfX,
					parts[2],
					insideX,
					structure[1],
					submodule.SpanLeast.At(lineRingOps, vectors, G, generated)))
			a.Take(m)
			l := a.FixAs[Set[A]]("l")
			a.FixAs[A]("y")
			subL := a.Assume()
			source := a.TermAs[RingOps[A]]("restrict_ring(field_ring(M), X)")
			target := a.TermAs[RingOps[A]]("restrict_ring(field_ring(M), l)")
			agree := a.Have(
				"points over y agree on k[t]: they fix k and send t to y",
				"∀e f:A → A. ∀c:A. e ∈ «over»(l, y) ∧ f ∈ «over»(l, y) ∧ c ∈ «line» ⇒ e(c) = f(c)",
				Derive(func(b *Argument) {
					e := b.FixAs[Fun[A, A]]("e")
					f := b.FixAs[Fun[A, A]]("f")
					c := b.FixAs[A]("c")
					given := b.Assume()
					data := b.Have(
						"e and f are ring maps on X fixing k and sending t to y",
						"ring_homomorphism(restrict_ring(field_ring(M), X), restrict_ring(field_ring(M), l), e) ∧ "+
							"(∀x:A. x ∈ k ⇒ e(x) = x) ∧ "+
							"e(t) = y ∧ "+
							"ring_homomorphism(restrict_ring(field_ring(M), X), restrict_ring(field_ring(M), l), f) ∧ "+
							"(∀x:A. x ∈ k ⇒ f(x) = x) ∧ "+
							"f(t) = y",
						BySets(
							given,
							algebra_points.AlgebraPointsMember.At(source, target, k, identity, e),
							algebra_points.AlgebraPointsMember.At(source, target, k, identity, f)))
					b.Show(
						"two ring maps agreeing on k and at t agree on k[t]",
						By(
							data,
							given,
							kInX,
							tInX,
							integral_element.PolynomialImageAgreement.Read(M).At(target, X, k, e, f, t, c)))
				}))
			inGenerated := a.Have(
				"they are points of k[t][G]",
				"«over»(l, y) ⊆ "+
					"algebra_points(restrict_ring(field_ring(M), «generated»(G)), "+
					"    restrict_ring(field_ring(M), l), "+
					"    k, "+
					"    λx:A. x)",
				BySets(equal))
			a.Show(
				"so there are at most m of them",
				By(bound.At(l, a.TermAs[Set[Fun[A, A]]]("«over»(l, y)")), subL, inGenerated, agree))
		}),
})}
